def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if value is None:
        return None
    return str(value)

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    # If it's already a string, return it
    if isinstance(value, str):
        return value
    # If it has an isoformat method, use it
    if hasattr(value, "isoformat"):
        try:
            return value.isoformat()
        except Exception:
            pass
    # Try to format using hour, minute, second attributes
    try:
        hour = getattr(value, "hour", None)
        minute = getattr(value, "minute", None)
        second = getattr(value, "second", None)
        if hour is not None and minute is not None and second is not None:
            return f"{hour:02d}:{minute:02d}:{second:02d}"
    except Exception:
        pass
    # Fallback: convert to string
    return str(value)

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        return None
    data = {'x': value.x, 'y': value.y}
    if hasattr(value, 'z'):
        data['z'] = value.z
    return data

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    return list(self.__dict__.keys())

def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Ensure the class has a registry of handlers
        if not hasattr(cls, "_protocol_handlers"):
            # If no registry is defined, return an empty dict
            return {}

        if protocol_version is not None:
            if not isinstance(protocol_version, tuple):
                raise TypeError("protocol_version must be a tuple, got %r" % (protocol_version,))
            handler = cls._protocol_handlers.get(protocol_version)
            return {protocol_version: handler} if handler is not None else {}

        # Return a copy of the full registry to avoid accidental mutation
        return dict(cls._protocol_handlers)

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    for i, item in enumerate(self):
        if item == key:
            return i
    raise ValueError(f"{key} is not in list")

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # If no keys are provided, return all values
    if not keys:
        try:
            # Try to get values from a mapping
            return list(self._record.values())
        except AttributeError:
            # Fallback to treating _record as an iterable of values
            return list(self._record)

    # If keys are provided, filter accordingly
    result = []
    for key in keys:
        if isinstance(key, int):
            # Treat key as an index
            try:
                result.append(self._record[key])
            except (IndexError, TypeError):
                raise IndexError(f"Index {key} out of range")
        else:
            # Treat key as a dictionary key
            try:
                result.append(self._record[key])
            except (KeyError, TypeError):
                raise KeyError(f"Key {key} not found")
    return result

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Assume the record stores its items as a list of (key, value) tuples
    # in an attribute called `_items`. Adjust if the actual attribute name
    # differs.
    items = getattr(self, "_items", None)
    if items is None:
        # Fallback: try to iterate over the object if it behaves like a dict
        try:
            items = list(self.items())
        except AttributeError:
            raise AttributeError("Record object does not provide an '_items' attribute or a .items() method")

    if not keys:
        # Return all items as a dictionary
        return {k: v for k, v in items}

    result = {}
    for key in keys:
        if isinstance(key, int):
            # Treat as index
            if key < 0 or key >= len(items):
                raise IndexError(f"Index {key} out of bounds")
            k, v = items[key]
            result[k] = v
        else:
            # Treat as key
            found = False
            for k, v in items:
                if k == key:
                    result[k] = v
                    found = True
                    break
            if not found:
                result[key] = None
    return result

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    attrs = {'srid_map': srid_map}
    def __init__(self, *args, **kwargs):
        super(self.__class__, self).__init__(*args)
        for f in fields:
            setattr(self, f, kwargs.get(f))
    attrs['__init__'] = __init__
    def __repr__(self):
        field_vals = ', '.join(f'{f}={getattr(self, f)!r}' for f in fields)
        return f'{name}({field_vals})'
    attrs['__repr__'] = __repr__
    return type(name, (Point,), attrs)

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(f"{func.__name__} is deprecated: {message}", DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    # Split the string on dots and convert each component to an integer.
    # Non-numeric components are ignored or treated as zero.
    parts = s.split('.')
    nums = []
    for part in parts:
        # Try to parse the whole part as an integer.
        try:
            nums.append(int(part))
            continue
        except ValueError:
            # If the part contains non-digit characters, extract the leading digits.
            digits = ''
            for ch in part:
                if ch.isdigit():
                    digits += ch
                else:
                    break
            if digits:
                nums.append(int(digits))
            else:
                # If no digits found, treat as zero.
                nums.append(0)
    return tuple(nums)

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorating_function(user_function):
        cache = {}
        freq = {}
        order = {}
        def make_key(args, kwds, typed):
            key = args
            if kwds:
                key += tuple(sorted(kwds.items()))
            if typed:
                key += tuple(type(v) for v in args)
                if kwds:
                    key += tuple(type(v) for k, v in sorted(kwds.items()))
            return key
        def wrapper(*args, **kwds):
            key = make_key(args, kwds, typed)
            if key in cache:
                freq[key] += 1
                return cache[key]
            result = user_function(*args, **kwds)
            cache[key] = result
            freq[key] = 1
            order[key] = len(order)
            if len(cache) > maxsize:
                min_freq = min(freq.values())
                candidates = [k for k, f in freq.items() if f == min_freq]
                evict_key = min(candidates, key=lambda k: order[k])
                del cache[evict_key]
                del freq[evict_key]
                del order[evict_key]
            return result
        wrapper.cache_info = lambda: (len(cache), maxsize)
        return wrapper
    return decorating_function

def setdefault(self, key, default=None):
    """D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D"""
    if key in self:
        return self[key]
    else:
        self[key] = default
        return default

def directlyProvidedBy(object):  # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    # If the object itself has a __provides__ attribute, return it
    if hasattr(object, "__provides__"):
        return object.__provides__
    # If the object is a class, look for __provides__ on the class
    if isinstance(object, type):
        return getattr(object, "__provides__", set())
    # For instances, look at the class
    return getattr(object.__class__, "__provides__", set())

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    # If the class defines an __interface__ dict, use it
    if hasattr(self.__class__, "__interface__"):
        if all:
            result = {}
            for cls in self.__class__.__mro__:
                if hasattr(cls, "__interface__"):
                    result.update(cls.__interface__)
            return result
        else:
            return dict(self.__class__.__interface__)

    # Fallback introspection
    result = {}
    if all:
        names = dir(self.__class__)
    else:
        names = self.__class__.__dict__.keys()
    for name in names:
        if name.startswith("_"):
            continue
        obj = getattr(self.__class__, name, None)
        if obj is None:
            continue
        if isinstance(obj, property):
            desc = obj.__doc__
        elif callable(obj):
            desc = obj.__doc__
        else:
            desc = None
        result[name] = desc
    return result

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    for item in sequence:
        # If the item is a Declaration, expand its interfaces
        try:
            # Declaration objects are expected to expose an ``interfaces`` attribute
            # or a ``get_interfaces()`` method that returns an iterable of interfaces.
            if hasattr(item, "interfaces"):
                interfaces = item.interfaces
            elif hasattr(item, "get_interfaces"):
                interfaces = item.get_interfaces()
            else:
                interfaces = None
        except Exception:
            interfaces = None

        if interfaces is not None:
            # Recursively normalize the interfaces from the Declaration
            output.extend(_normalizeargs(interfaces))
        elif isinstance(item, (tuple, list)):
            # Flatten nested tuples/lists
            output.extend(_normalizeargs(item))
        else:
            # Assume the item is an individual interface or implements spec
            output.append(item)

    return output

def _c_optimizations_ignored(self):
    """The opposite of `_c_optimizations_required`."""
    return not self._c_optimizations_required()

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the current context
    self.context = {}

    # Reinitialize bins
    if getattr(self, 'initial_value', None) is not None:
        # If bins are stored in a dict, set each value to the initial value
        if isinstance(self.bins, dict):
            for key in self.bins:
                self.bins[key] = self.initial_value
        # Otherwise assume bins is a list/tuple and set each element
        else:
            for i in range(len(self.bins)):
                self.bins[i] = self.initial_value
    else:
        # Recreate bins using the factory method
        self.bins = self.make_bins()

def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    lines = []
    if header is not None:
        lines.append(str(header))
    for point in self:
        # Extract coordinates
        try:
            coords = point.coords
        except AttributeError:
            # If point is a tuple/list of (coords, value)
            if isinstance(point, (list, tuple)) and len(point) == 2:
                coords, value = point
            else:
                raise ValueError("Point does not have a 'coords' attribute")
        else:
            value = getattr(point, "value", None)
        # Convert coordinates to string
        coord_parts = [str(c) for c in coords]
        # Convert value to string parts
        if isinstance(value, (list, tuple)):
            val_parts = [str(v) for v in value]
        else:
            try:
                # Check for iterable but not string/bytes
                iter(value)
                if isinstance(value, (str, bytes)):
                    val_parts = [str(value)]
                else:
                    val_parts = [str(v) for v in value]
            except TypeError:
                val_parts = [str(value)]
        line = separator.join(coord_parts + val_parts)
        lines.append(line)
    return "\n".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # The error indices are stored in a dictionary mapping coordinate names to lists of indices.
    # If the coordinate is not present, return an empty list.
    if not hasattr(self, "_err_indices"):
        return []
    return list(self._err_indices.get(coord_name, []))

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # If seq itself is a FillRequest element, it's valid
    if isinstance(seq, FillRequest):
        return True
    # If seq is a Source sequence, it's not valid
    if isinstance(seq, Source):
        return False
    # If seq is iterable, check if any element is a FillRequest
    try:
        for e in seq:
            if isinstance(e, FillRequest):
                return True
    except TypeError:
        # seq is not iterable
        pass
    return False

