def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both arguments must be dictionaries")

    result = {}
    for key, val in d1.items():
        if key not in d2:
            result[key] = val
        else:
            val2 = d2[key]
            # Determine if we should recurse into nested dictionaries
            if isinstance(val, dict) and isinstance(val2, dict) and level != 0:
                sublevel = level - 1 if level > 0 else -1
                subdiff = difference(val, val2, sublevel)
                if subdiff:
                    result[key] = subdiff
            else:
                if val != val2:
                    result[key] = val
    return result

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re

    errors = []

    # Helper to format regex pattern for error message
    def _regex_pattern(regex):
        try:
            return regex.pattern
        except AttributeError:
            return str(regex)

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            # Validate key regex
            if not LABEL_KEY_REGEX.match(key):
                errors.append(
                    {key: f"Label key '{key}' does not match the regex [{_regex_pattern(LABEL_KEY_REGEX)}]"}
                )

        # Validate value(s)
        # If the value is a list or tuple, iterate each element
        if isinstance(value, (list, tuple)):
            for v in value:
                if not isinstance(v, (str, bytes)):
                    errors.append({str(v): 'expected string or bytes-like object'})
                else:
                    if not LABEL_VALUE_REGEX.match(v):
                        errors.append(
                            {v: f"Label value '{v}' does not match the regex [{_regex_pattern(LABEL_VALUE_REGEX)}]"}
                        )
        else:
            if not isinstance(value, (str, bytes)):
                errors.append({str(value): 'expected string or bytes-like object'})
            else:
                if not LABEL_VALUE_REGEX.match(value):
                    errors.append(
                        {value: f"Label value '{value}' does not match the regex [{_regex_pattern(LABEL_VALUE_REGEX)}]"}
                    )

    if errors:
        raise ValidationError(messages=errors)

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Ensure the observer_schema attribute exists
    if not hasattr(app.spec, 'observer_schema') or app.spec.observer_schema is None:
        app.spec.observer_schema = {}

    # Iterate over each resource in the manifest
    for res in getattr(app.spec, 'manifest', []):
        kind = getattr(res, 'kind', None)
        if not kind:
            continue

        # Skip if a custom schema already exists for this kind
        if kind in app.spec.observer_schema:
            continue

        # Create a simple default schema: observe name and namespace
        default_schema = {
            'metadata': {
                'name': True,
                'namespace': True
            }
        }
        app.spec.observer_schema[kind] = default_schema

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        import os
    except Exception:
        return False

    # Resolve root path
    if isinstance(path, str):
        root = path
    else:
        try:
            root = path.path
        except AttributeError:
            return False

    if not os.path.isdir(root):
        return False

    # Check for .ocfl_version file
    ocfl_version_file = os.path.join(root, '.ocfl_version')
    if not os.path.isfile(ocfl_version_file):
        return False
    try:
        with open(ocfl_version_file, 'r') as f:
            version = f.read().strip()
        if not version:
            return False
    except Exception:
        return False

    # Check for objects directory
    objects_dir = os.path.join(root, 'objects')
    if not os.path.isdir(objects_dir):
        return False

    # Ensure at least one object exists
    try:
        entries = [e for e in os.listdir(objects_dir)
                   if os.path.isdir(os.path.join(objects_dir, e))]
    except Exception:
        return False
    if not entries:
        return False

    # Optional: verify each object has a manifest file
    for obj_id in entries:
        obj_dir = os.path.join(objects_dir, obj_id)
        manifest_file = os.path.join(obj_dir, 'manifest')
        if not os.path.isfile(manifest_file):
            return False

    return True

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    status = getattr(self, 'status', None)
    if status is None:
        return prefix
    return f"{prefix}{status}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Assume the log entries are stored in an iterable attribute of the instance.
    # If the instance itself is iterable, use it directly.
    try:
        entries = iter(self)
    except TypeError:
        # Fallback to common attribute names
        entries = getattr(self, 'log', getattr(self, 'entries', []))
    return '\n'.join(prefix + str(entry) for entry in entries)

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type check for the inventory
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")

    # Determine the specification version to use for validation
    spec_version = self.spec_version
    if extract_spec_version:
        inv_type = inventory.get("type")
        # Assume the class has a mapping of supported types to spec versions
        if hasattr(self, "SUPPORTED_TYPES") and isinstance(self.SUPPORTED_TYPES, dict):
            if inv_type in self.SUPPORTED_TYPES:
                spec_version = self.SUPPORTED_TYPES[inv_type]
        # If the type is missing or not recognised, fall back to self.spec_version

    # Validate that the inventory contains the required top‑level keys
    required_keys = ["items"]
    for key in required_keys:
        if key not in inventory:
            raise ValueError(f"Missing required key '{key}' in inventory")

    # If a spec_version key is present, it must match the one we are using
    if "spec_version" in inventory:
        if inventory["spec_version"] != spec_version:
            raise ValueError(
                f"Inventory spec_version '{inventory['spec_version']}' does not match "
                f"expected '{spec_version}'"
            )

    # Validate the items list
    items = inventory["items"]
    if not isinstance(items, list):
        raise TypeError("inventory['items'] must be a list")

    for idx, item in enumerate(items):
        if not isinstance(item, dict):
            raise TypeError(f"Item {idx} in inventory['items'] must be a dict")
        # Example required fields for each item; adjust as needed
        for field in ("id", "name"):
            if field not in item:
                raise ValueError(f"Item {idx} missing required field '{field}'")

    # All checks passed
    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Normalize manifest_files to an iterable of (file, digest) pairs
    if isinstance(manifest_files, dict):
        manifest_iter = manifest_files.items()
    else:
        try:
            # Assume iterable of (file, digest) tuples
            manifest_iter = iter(manifest_files)
        except TypeError:
            raise TypeError("manifest_files must be a dict or an iterable of (file, digest) pairs")

    missing = []
    for file, digest in manifest_iter:
        if digest not in digests_used:
            missing.append((file, digest))

    if missing:
        msg_parts = [f"{f} (digest={d})" for f, d in missing]
        raise ValueError("Missing digests for files: " + ", ".join(msg_parts))

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise TypeError("fixity must be a dict")
    if 'files' not in fixity:
        raise ValueError("fixity block missing 'files' key")
    files = fixity['files']
    if not isinstance(files, list):
        raise TypeError("'files' must be a list")
    if not isinstance(manifest_files, (set, list, tuple)):
        raise TypeError("manifest_files must be a set or list")
    manifest_set = set(manifest_files)

    seen = set()
    for entry in files:
        if not isinstance(entry, dict):
            raise TypeError("each file entry must be a dict")
        if 'path' not in entry:
            raise ValueError("file entry missing 'path'")
        path = entry['path']
        if not isinstance(path, str):
            raise TypeError("file path must be a string")
        if path not in manifest_set:
            raise ValueError(f"file '{path}' in fixity block not found in manifest")
        if path in seen:
            raise ValueError(f"duplicate file entry for '{path}' in fixity block")
        seen.add(path)
        if 'hash' not in entry:
            raise ValueError(f"file entry for '{path}' missing 'hash'")
        if not isinstance(entry['hash'], str):
            raise TypeError(f"hash for file '{path}' must be a string")
        if 'size' in entry and not isinstance(entry['size'], int):
            raise TypeError(f"size for file '{path}' must be an int")

    return True

