def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    indent_str = ' ' * indent
    lines = [f"{indent_str}{self.__class__.__name__}("]
    for key, value in self.__dict__.items():
        if isinstance(value, list):
            lines.append(f"{indent_str}  {key}=[")
            for item in value:
                if hasattr(item, "pretty"):
                    lines.append(item.pretty(indent + 4, debug))
                else:
                    lines.append(f"{indent_str}    {repr(item)}")
            lines.append(f"{indent_str}  ]")
        elif hasattr(value, "pretty"):
            lines.append(value.pretty(indent + 2, debug))
        else:
            lines.append(f"{indent_str}  {key}={repr(value)}")
    lines.append(f"{indent_str})")
    return "\n".join(lines)

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    def wrapper(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        if sys.version_info[0] < 3:
            if isinstance(result, tuple):
                result = tuple([x.encode('utf-8') if isinstance(x, unicode) else x for x in result])
            elif isinstance(result, unicode):
                result = result.encode('utf-8')
        return result
    return wrapper

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        from importlib.metadata import version, PackageNotFoundError
    except ImportError:
        try:
            from importlib_metadata import version, PackageNotFoundError
        except ImportError:
            return {"version": "0.0.0", "full-revisionid": None, "dirty": False, "error": "importlib.metadata not available"}
    pkg_name = __package__ or __name__
    try:
        ver = version(pkg_name)
    except PackageNotFoundError:
        return {"version": "0.0.0", "full-revisionid": None, "dirty": False, "error": f"package {pkg_name} not found"}
    return {"version": ver, "full-revisionid": None, "dirty": False, "error": None}

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if not isinstance(pieces, (list, tuple)):
        raise TypeError("pieces must be a list or tuple of strings or objects")
    if style == 'plain':
        return ''.join(str(p) for p in pieces)
    elif style == 'html':
        return ''.join(f'<span>{p}</span>' for p in pieces)
    elif style == 'markdown':
        return ''.join(f'`{p}`' for p in pieces)
    else:
        raise ValueError(f"Unsupported style: {style}")

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    for p in pieces:
        if p == '+':
            return '.'
    return '+'

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    def decorator(func):
        global _VCS_HANDLERS
        if '_VCS_HANDLERS' not in globals():
            _VCS_HANDLERS = {}
        _VCS_HANDLERS[vcs] = func
        return func
    return decorator

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    stack = [self]
    while stack:
        node = stack.pop()
        num_objects += 1
        valid = True
        if validate_objects:
            try:
                if hasattr(node, 'validate'):
                    valid = node.validate()
                else:
                    valid = True
            except Exception as e:
                valid = False
                if show_warnings:
                    import warnings
                    warnings.warn(f"Validation error for {node}: {e}")
        if check_digests and valid:
            try:
                if hasattr(node, 'check_digest'):
                    valid = node.check_digest()
                else:
                    valid = True
            except Exception as e:
                valid = False
                if show_warnings:
                    import warnings
                    warnings.warn(f"Digest check error for {node}: {e}")
        if valid:
            good_objects += 1
        # Add children to stack for further validation
        children = getattr(node, 'children', None)
        if children:
            stack.extend(children)
        else:
            try:
                for child in node:
                    stack.append(child)
            except TypeError:
                pass
    return num_objects, good_objects

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Ensure we have a place to record differences
    self.different_digests = {}
    # The root inventory should already be available as a dict mapping path -> digest
    if not hasattr(self, 'root_inventory') or not isinstance(self.root_inventory, dict):
        raise ValueError("Root inventory not available or not a dict")
    for vdir in version_dirs:
        inv_path = os.path.join(vdir, 'inventory.xml')
        if not os.path.exists(inv_path):
            raise ValueError(f"Missing inventory file in version directory '{vdir}'.")
        try:
            tree = ET.parse(inv_path)
            root = tree.getroot()
        except Exception as e:
            raise ValueError(f"Failed to parse inventory in '{vdir}': {e}")
        # Iterate over all file entries in the inventory
        for file_elem in root.findall('.//file'):
            path = file_elem.get('path')
            digest = file_elem.get('digest')
            if path is None or digest is None:
                continue
            root_digest = self.root_inventory.get(path)
            if root_digest is None:
                # File not present in the root inventory; ignore or log as needed
                continue
            if digest != root_digest:
                # Record the version where the digest differs
                self.different_digests.setdefault(path, []).append(vdir)
    # Return the differences for further validation if needed
    return self.different_digests

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""

    if not isinstance(params, dict):
        raise TypeError("params must be a dict")

    # Normalise bug_ids to a list of strings
    if bug_ids is None:
        return params
    if isinstance(bug_ids, (list, tuple, set)):
        ids = [str(b) for b in bug_ids]
    else:
        ids = [str(bug_ids)]

    # Merge with any existing 'ids' entry
    existing = params.get('ids')
    if existing:
        if isinstance(existing, str):
            existing_ids = existing.split(',')
        else:
            existing_ids = [str(existing)]
        merged = sorted(set(existing_ids) | set(ids), key=int)
        params['ids'] = ','.join(merged)
    else:
        params['ids'] = ','.join(ids)

    return params

