def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.strip()
    if not size:
        raise ValueError("Size string is empty")

    # Separate numeric part from unit
    num_str = ""
    unit_str = ""
    for ch in size:
        if ch.isdigit() or ch == ".":
            num_str += ch
        else:
            unit_str += ch

    if not num_str:
        raise ValueError(f"Invalid size format: {size}")

    try:
        num = float(num_str)
    except ValueError:
        raise ValueError(f"Invalid numeric value: {num_str}")

    unit = unit_str.strip().upper()
    factor = 1
    if unit:
        if unit in ("K", "KB"):
            factor = 1000
        elif unit in ("M", "MB"):
            factor = 1000**2
        elif unit in ("G", "GB"):
            factor = 1000**3
        elif unit in ("T", "TB"):
            factor = 1000**4
        elif unit in ("P", "PB"):
            factor = 1000**5
        elif unit in ("E", "EB"):
            factor = 1000**6
        else:
            raise ValueError(f"Unknown unit: {unit}")

    return int(round(num * factor))

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for key, value in d.items():
            result[key] = result.get(key, 0) + value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url_args:
        return url
    import re
    # Matches {key} or :key patterns
    pattern = re.compile(r'\{([^}]+)\}|\:([^\s/]+)')
    def repl(match):
        key = match.group(1) or match.group(2)
        return str(url_args.get(key, match.group(0)))
    return pattern.sub(repl, url)

