def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet must contain at least one symbol.")
    if number < 0:
        raise ValueError("Negative numbers are not supported.")
    base = len(alphabet)
    # Special case for zero
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        result = ''.join(reversed(digits))
    if padding is not None:
        if padding < 0:
            raise ValueError("Padding must be non-negative.")
        pad_len = padding - len(result)
        if pad_len > 0:
            result = alphabet[0] * pad_len + result
    return result

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    # If flow_params is a dictionary, replace the value for the given key
    if isinstance(flow_params, dict):
        if register_value in flow_params:
            flow_params[register_value] = register_number
        # Also check nested dictionaries
        for v in flow_params.values():
            if isinstance(v, dict) and register_value in v:
                v[register_value] = register_number
    # If flow_params is a list of dictionaries, iterate over each dict
    elif isinstance(flow_params, list):
        for item in flow_params:
            if isinstance(item, dict) and register_value in item:
                item[register_value] = register_number
    # If flow_params is a single dictionary (not nested), replace directly
    elif isinstance(flow_params, dict):
        if register_value in flow_params:
            flow_params[register_value] = register_number

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    subs = set()
    for subclass in cls.__subclasses__():
        subs.add(subclass)
        subs.update(subclasses(subclass))
    return list(subs)

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    base = len(alphabet)
    if base <= 1:
        raise ValueError("Alphabet must contain at least two symbols")
    value = 0
    for ch in string:
        try:
            digit = alphabet.index(ch)
        except ValueError:
            raise ValueError(f"Character '{ch}' not in alphabet")
        value = value * base + digit
    return value

def unquote(name):
    """Remove quote from the given name."""
    if not name:
        return name
    if (name[0] == name[-1]) and name[0] in ('"', "'"):
        return name[1:-1]
    return name

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    output = subprocess.check_output(['git', 'ls-files', '--others', '--ignored', '--exclude-standard'])
    files = output.decode().splitlines()
