def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    return np.exp(-((x - 0.2) ** 2) / (2 * 0.1 ** 2))

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    results = {}
    errors = []
    logger = logging.getLogger(__name__)
    for fname in config_filenames:
        try:
            with open(fname, 'r') as f:
                content = f.read()
            # Basic validation: file must not be empty
            if not content.strip():
                msg = f"Configuration file '{fname}' is empty."
                record = logging.LogRecord(logger.name, logging.ERROR, fname, 0, msg, None, None)
                errors.append(record)
                continue
            # If overrides are provided and the content looks like a dictionary, attempt to apply them
            if overrides and isinstance(overrides, dict) and fname in overrides:
                # Try to interpret the content as a simple key=value format
                config_dict = {}
                for line in content.splitlines():
                    line = line.strip()
                    if not line or line.startswith('#'):
                        continue
                    if '=' in line:
                        key, val = line.split('=', 1)
                        config_dict[key.strip()] = val.strip()
                # Apply overrides
                config_dict.update(overrides[fname])
                results[fname] = config_dict
            else:
                results[fname] = content
        except Exception as e:
            msg = f"Error loading configuration file '{fname}': {e}"
            record = logging.LogRecord(logger.name, logging.ERROR, fname, 0, msg, None, None)
            errors.append(record)
    return results, errors

def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple")
        if protocol_version in cls._protocol_handlers:
            return {protocol_version: cls._protocol_handlers[protocol_version]}
        return {}
    # Return all available handlers
    return dict(cls._protocol_handlers)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Define what we consider a sequence type
    seq_types = (list, tuple, str, bytes, bytearray, memoryview)
    if isinstance(seq, seq_types):
        return seq, type(seq)
    # If not a known sequence type, try to convert to a list
    try:
        seq_list = list(seq)
    except TypeError:
        raise TypeError(f"Provided seq {seq!r} is not iterable")
    return seq_list, type(seq_list)

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Return current scale if no new value is provided
    if other is None:
        return getattr(self, "scale", None)

    # Ensure the new scale is numeric
    try:
        new_scale = float(other)
    except Exception as exc:
        raise TypeError("Scale must be a numeric value") from exc

    # Check that the current scale is known and non‑zero
    current_scale = getattr(self, "scale", None)
    if current_scale is None or current_scale == 0:
        raise LenaValueError("Cannot rescale graph with unknown or zero scale")

    # Compute the scaling factor
    factor = new_scale / current_scale

    # Determine the index of the last coordinate (based on fields)
    fields = getattr(self, "fields", None)
    if fields and isinstance(fields, (list, tuple)):
        last_index = len(fields) - 1
    else:
        # Fallback: assume 2‑D if fields are unknown
        last_index = 1

    # Rescale the data points (only the last coordinate)
    data = getattr(self, "data", None)
    if data and isinstance(data, (list, tuple)):
        new_data = []
        for point in data:
            if isinstance(point, (list, tuple)):
                pt = list(point)
                if len(pt) > last_index:
                    pt[last_index] *= factor
                new_data.append(tuple(pt))
            else:
                new_data.append(point)
        setattr(self, "data", new_data)

    # Rescale the errors (only the last coordinate)
    errors = getattr(self, "errors", None)
    if errors and isinstance(errors, (list, tuple)):
        for err in errors:
            # If the error object stores coordinates in a list/tuple
            if hasattr(err, "coord"):
                coord = getattr(err, "coord")
                if isinstance(coord, (list, tuple)):
                    new_coord = tuple(
                        c * factor if idx == last_index else c
                        for idx, c in enumerate(coord)
                    )
                    setattr(err, "coord", new_coord)
            # Fallback: try individual attributes (x, y, z)
            for attr in ("x", "y", "z"):
                if hasattr(err, attr):
                    if attr == fields[last_index] if fields else attr == "y":
                        setattr(err, attr, getattr(err, attr) * factor)

    # Update the graph's scale
    setattr(self, "scale", new_scale)
    return self

def _verify(iface, candidate, tentative=False, vtype=None):
    import inspect
    from zope.interface import Invalid, providedBy
    errors = []

    if not tentative:
        if not providedBy(candidate):
            raise Invalid(f"{candidate!r} does not provide {iface.__name__}")

    # Check methods
    for name, method in iface.methods.items():
        if not hasattr(candidate, name):
            errors.append(f"Missing method {name}")
            continue
        attr = getattr(candidate, name)
        if not callable(attr):
            errors.append(f"{name} is not callable")
            continue
        iface_sig = getattr(method, "__signature__", None)
        if iface_sig is not None:
            try:
                cand_sig = inspect.signature(attr)
            except Exception:
                cand_sig = None
            if cand_sig is not None and cand_sig != iface_sig:
                errors.append(f"Signature mismatch for {name}: expected {iface_sig}, got {cand_sig}")

    # Check attributes
    for name, attr in iface.attributes.items():
        if not hasattr(candidate, name):
            errors.append(f"Missing attribute {name}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    # If iface is a class or type, check subclass/instance relationship
    if isinstance(iface, type):
        if isinstance(candidate, type):
            return issubclass(candidate, iface)
        else:
            return isinstance(candidate, iface)

    # If iface is a collection of attribute names (e.g., a protocol specification)
    if isinstance(iface, (list, tuple, set)):
        for name in iface:
            if not hasattr(candidate, name):
                if tentative:
                    continue
                return False
        return True

    # If iface is a callable that can validate the candidate
    if callable(iface):
        try:
            return bool(iface(candidate))
        except Exception:
            return False

    # Fallback: compare public attributes of iface and candidate
    if hasattr(iface, "__dict__"):
        for name in dir(iface):
            if name.startswith("_"):
                continue
            if not hasattr(candidate, name):
                if tentative:
                    continue
                return False
        return True

    # If none of the above, we cannot verify
    return False

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc

    if not bases:
        raise TypeError("determineMetaclass requires at least one base class")

    # Start with the metaclass of the first base
    metaclass = type(bases[0])

    for base in bases[1:]:
        base_meta = type(base)

        # If the current metaclass is already a subclass of the base's metaclass,
        # it is compatible; otherwise, if the base's metaclass is a subclass,
        # use that one.
        if issubclass(metaclass, base_meta):
            continue
        if issubclass(base_meta, metaclass):
            metaclass = base_meta
            continue

        # Find the most derived common ancestor of the two metaclasses.
        for m in metaclass.mro():
            if m in base_meta.mro():
                metaclass = m
                break
        else:
            raise TypeError(
                "metaclass conflict: %r and %r" % (metaclass, base_meta)
            )

    return metaclass

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError('popitem(): dictionary is empty')
    # Determine the key with the lowest frequency
    if hasattr(self, '_freq') and isinstance(self._freq, dict):
        # Find key with minimum frequency
        min_key = min(self._freq, key=lambda k: self._freq[k])
    else:
        # Fallback: use the first key (no frequency information)
        min_key = next(iter(self))
    value = self[min_key]
    # Remove the key from the dictionary
    del self[min_key]
    # Remove frequency record if present
    if hasattr(self, '_freq') and isinstance(self._freq, dict):
        self._freq.pop(min_key, None)
    return (min_key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    return self._data.popitem(last=False)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    return super().popitem(last=True)

def _create_in_regex(self) -> Pattern:
    """Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    import re
    return re.compile(r'\bin\s*:?\\s*([^\s]+)')

def _create_converter(self) -> _converting._Converter:
    """Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    return _converting._Converter()

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Check for a public Diaspora message
    try:
        if getattr(request, "public", None):
            return True
    except Exception:
        pass

    # Check for a private Diaspora message
    try:
        if getattr(request, "private", None):
            return True
    except Exception:
        pass

    # Check for a legacy Diaspora payload
    try:
        if getattr(request, "legacy", None):
            return True
    except Exception:
        pass

    # Fallback: inspect a type attribute if present
    try:
        if getattr(request, "type", None) in (
            "diaspora_public",
            "diaspora_private",
            "diaspora_legacy",
        ):
            return True
    except Exception:
        pass

    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    # Check for typical Matrix request indicators
    # 1. Header 'Matrix-Request' present
    # 2. Path starts with '/matrix'
    # 3. Content-Type 'application/matrix'
    # 4. Attribute 'matrix' or 'is_matrix' True
    try:
        # Header check
        if hasattr(request, 'headers') and isinstance(request.headers, dict):
            if request.headers.get('Matrix-Request') is not None:
                return True
            if request.headers.get('Content-Type') == 'application/matrix':
                return True
        # Path check
        if hasattr(request, 'path') and isinstance(request.path, str):
            if request.path.lower().startswith('/matrix'):
                return True
        # Attribute check
        if hasattr(request, 'matrix') and getattr(request, 'matrix'):
            return True
        if hasattr(request, 'is_matrix') and getattr(request, 'is_matrix'):
            return True
    except Exception:
        pass
    return False

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    if dt is None:
        return None
    # If the object has an hour attribute, treat it as a datetime
    if hasattr(dt, "hour"):
        # Remove microseconds if present
        if hasattr(dt, "microsecond"):
            try:
                dt = dt.replace(microsecond=0)
            except Exception:
                pass
        return dt.strftime("%Y-%m-%dT%H:%M:%S")
    # Otherwise treat it as a date
    return dt.strftime("%Y-%m-%d")

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    # Find all fenced code blocks (```) and record their spans
    code_blocks = []
    for m in re.finditer(r'```.*?```', text, flags=re.DOTALL):
        code_blocks.append((m.start(), m.end()))

    def in_code_block(pos: int) -> bool:
        """Return True if the position is inside any code block."""
        for start, end in code_blocks:
            if start <= pos < end:
                return True
        return False

    tags: Set[str] = set()

    if replacer:
        # Replacement function that skips tags inside code blocks
        def repl_func(match: re.Match) -> str:
            tag = match.group(0)
            if in_code_block(match.start()):
                return tag
            tags.add(tag)
            return replacer(tag)

        new_text = re.sub(r'#\w+', repl_func, text)
    else:
        # Just collect tags that are not inside code blocks
        for m in re.finditer(r'#\w+', text):
            if not in_code_block(m.start()):
                tags.add(m.group(0))
        new_text = text

    return tags, new_text

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    try:
        import urllib.request
        req = urllib.request.Request(url, method='HEAD')
        with urllib.request.urlopen(req, timeout=10) as resp:
            return resp.info().get_content_type()
    except Exception:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    import re
    # A tag must start with a letter and can contain letters, digits, underscores or hyphens.
    pattern = re.compile(r'^[A-Za-z][A-Za-z0-9_-]*$')
    return bool(pattern.match(tag))

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    result = {}
    for child in node:
        key = child.tag
        if key in result:
            # If we already have a single element, convert to list
            if isinstance(result[key], list):
                result[key].append(child)
            else:
                result[key] = [result[key], child]
        else:
            result[key] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if not url:
        raise ValueError("url must be provided")
    base = url.rstrip('/')
    if document_path is None:
        doc_path = '/.well-known/nodeinfo'
    else:
        doc_path = document_path
    if not doc_path.startswith('/'):
        doc_path = '/' + doc_path
    href = f"{base}{doc_path}/2.0"
    return {"links": [{"rel": "http://nodeinfo.diaspora.software/ns/schema/2.0", "href": href}]}

def verify_relayable_signature(public_key, doc, signature):
    """Verify the signed XML elements to have confidence that the claimed author did actually generate this message."""
    try:
        import xmlsec
    except ImportError:
        return False
    ctx = xmlsec.SignatureContext()
    if isinstance(public_key, str):
        key = xmlsec.Key.from_file(public_key, xmlsec.KeyFormat.PEM)
    else:
        key = public_key
    ctx.key = key
    try:
        ctx.verify(signature)
        return True
    except xmlsec.VerificationError:
        return False

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Try JSON first
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            return {
                'subject': data.get('subject'),
                'aliases': data.get('aliases', []),
                'links': data.get('links', [])
            }
    except json.JSONDecodeError:
        pass

    # Try XRD (XML)
    try:
        root = ET.fromstring(document)
        ns = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}

        def find_text(tag):
            return root.findtext(tag) or root.findtext(f'{{{ns["xrd"]}}}{tag}', namespaces=ns)

        subject = find_text('Subject')

        aliases = [e.text for e in root.findall('Alias')]
        if not aliases:
            aliases = [e.text for e in root.findall('xrd:Alias', namespaces=ns)]

        links = []
        for link in root.findall('Link'):
            href = link.get('href')
            rel = link.get('rel')
            type_ = link.get('type')
            links.append({'rel': rel, 'type': type_, 'href': href})
        if not links:
            for link in root.findall('xrd:Link', namespaces=ns):
                href = link.get('href')
                rel = link.get('rel')
                type_ = link.get('type')
                links.append({'rel': rel, 'type': type_, 'href': href})

        return {'subject': subject, 'aliases': aliases, 'links': links}
    except ET.ParseError:
        raise ValueError('Invalid webfinger document')

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        if '@' not in handle:
            return None
        host = handle.split('@', 1)[1]
        url = f"https://{host}/.well-known/webfinger?resource=acct:{handle}"
        req = urllib.request.Request(url, headers={'Accept': 'application/jrd+json'})
        with urllib.request.urlopen(req, timeout=5) as resp:
            if resp.status == 200:
                return resp.read().decode('utf-8')
    except Exception:
        pass
    return None

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    file_names = []
    for dir_path in settings_dirs:
        try:
            for entry in os.listdir(dir_path):
                full_path = os.path.join(dir_path, entry)
                if os.path.isfile(full_path):
                    if spec_option is None or entry.endswith(spec_option):
                        file_names.append(entry)
        except OSError:
            continue
    return file_names

