    """Gets the ansible config manager. """
    if not hasattr(cls, "_ansible_config_manager"):
        cls._ansible_config_manager = AnsibleConfigManager()
    return cls._ansible_config_manager

def workspace_manager(cls):
        """Gets the workspace manager. """
        if not hasattr(cls, '_workspace_manager'):
            cls._workspace_manager = WorkspaceManager()
        return cls._workspace_manager

def plugins_manager(cls):
    """Gets the plugin manager. """
    if not hasattr(cls, '_plugins_manager'):
        cls._plugins_manager = PluginManager()
    return cls._plugins_manager

def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException("No spec content provided")

        # Load YAML if we received a string, otherwise assume a dict
        if isinstance(spec_content, str):
            try:
                data = yaml.safe_load(spec_content)
            except Exception as exc:
                raise IRValidatorException(f"Error parsing YAML: {exc}")
        elif isinstance(spec_content, dict):
            data = spec_content
        else:
            raise IRValidatorException(
                f"Spec content must be a string or dict, got {type(spec_content).__name__}"
            )

        # Validate required fields if the class defines them
        required = getattr(cls, "REQUIRED_FIELDS", [])
        missing = [field for field in required if field not in data]
        if missing:
            raise IRValidatorException(
                f"Missing required fields in spec: {', '.join(missing)}"
            )

        return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    # Iterate over a copy of the items to allow modification during iteration
    for key, value in list(parser_dict.items()):
        # If the value is a nested dictionary, recurse into it
        if isinstance(value, dict):
            self._include_groups(value)
        # If the value is a string, treat it as a path to an include file
        elif isinstance(value, str):
            try:
                with open(value, 'r', encoding='utf-8') as f:
                    # Attempt to load the file as JSON; fall back to YAML if available
                    try:
                        import json
                        included = json.load(f)
                    except Exception:
                        try:
                            import yaml
                            included = yaml.safe_load(f)
                        except Exception:
                            raise ValueError(f"Unable to parse include file '{value}' as JSON or YAML")
                # Replace the string with the parsed content
                parser_dict[key] = included
                # Recursively resolve any includes inside the newly loaded content
                self._include_groups(included)
            except Exception as exc:
                raise ValueError(f"Failed to include group '{key}' from '{value}': {exc}") from exc
    # Return the modified dictionary for convenience
    return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    # Retrieve defaults from the specification
    spec = getattr(self, 'spec', {})
    for arg in spec.get('arguments', []):
        name = arg.get('name')
        if not name:
            continue
        # Skip if argument already provided
        if hasattr(self, 'args') and name in getattr(self, 'args', {}):
            continue
        if 'default' in arg:
            defaults[name] = arg['default']
    # Merge with any explicit defaults defined on the instance
    if hasattr(self, 'defaults'):
        for k, v in getattr(self, 'defaults', {}).items():
            defaults.setdefault(k, v)
    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    # Map deprecated argument names to the new argument names
    return {
        'old_option': 'new_option',
        'legacy_flag': 'modern_flag',
    }

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # A mapping of deprecated argument names to a deprecation message or the new argument name.
    # This attribute should be defined on the instance that uses this method.
    deprecated = getattr(self, 'deprecated_args', {})

    # Check CLI arguments for deprecated keys
    for arg in cli_args:
        if arg in deprecated:
            print(f"Warning: Argument '{arg}' is deprecated. {deprecated[arg]}")

    # Check answer file arguments for deprecated keys
    for arg in answer_file_args:
        if arg in deprecated:
            print(f"Warning: Argument '{arg}' is deprecated. {deprecated[arg]}")

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    return self.parser_options.get(command_name, [])

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Retrieve the command object; raise a clear error if it does not exist
    try:
        cmd = self.commands[command_name]
    except KeyError:
        raise KeyError(f"Command '{command_name}' not found")

    # Retrieve the option specification from the command; raise a clear error if it does not exist
    try:
        return cmd.options[argument_name]
    except KeyError:
        raise KeyError(f"Option '{argument_name}' not found in command '{command_name}'")

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent = []
    # If args is a mapping, return keys whose values are None or empty
    if isinstance(args, dict):
        for key, value in args.items():
            if value is None or value == '':
                silent.append(key)
    # If args is a list/tuple of (key, value) pairs, handle similarly
    elif isinstance(args, (list, tuple)):
        for item in args:
            if isinstance(item, (list, tuple)) and len(item) == 2:
                key, value = item
                if value is None or value == '':
                    silent.append(key)
    return silent

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for opt in options_spec:
        # Skip options that do not have a name or required_when
        if 'name' not in opt or 'required_when' not in opt:
            continue
        cond = opt['required_when']
        # If the condition is a callable, call it with the args dict
        if callable(cond):
            try:
                if cond(args):
                    required.append(opt['name'])
            except Exception:
                # If the callable raises, ignore this option
                continue
        else:
            # Assume the condition is a string expression that can be evaluated
            # with the args dictionary available as ``args``.
            try:
                if eval(cond, {}, {'args': args}):
                    required.append(opt['name'])
            except Exception:
                # If eval fails, ignore this option
                continue
    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Determine the maximum lengths to use for validation.
    # Prefer a per-argument mapping if available, otherwise fall back to a single max_length.
    max_lengths = getattr(self, 'max_lengths', None)
    single_max = getattr(self, 'max_length', None)

    for name, value in args.items():
        # Skip validation for None values or values without a length.
        if value is None or not hasattr(value, '__len__'):
            continue

        # Determine the applicable maximum length for this argument.
        if isinstance(max_lengths, dict):
            max_len = max_lengths.get(name, single_max)
        else:
            max_len = single_max

        # If no maximum length is defined, skip this argument.
        if max_len is None:
            continue

        # Perform the length check.
        if len(value) > max_len:
            raise ValueError(
                f"Argument '{name}' length {len(value)} exceeds maximum allowed {max_len}"
            )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Ensure the object has a mapping of allowed choices
    if not hasattr(self, "choices"):
        return

    for key, value in args.items():
        if key in self.choices:
            allowed = self.choices[key]
            if value not in allowed:
                raise ValueError(
                    f"Invalid value for argument '{key}': {value}. "
                    f"Allowed values: {allowed}"
                )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Determine if args is a mapping or an iterable
    if isinstance(args, dict):
        iterable = args.items()
    else:
        iterable = enumerate(args)

    for key, value in iterable:
        if not (self.min <= value <= self.max):
            raise ValueError(f"Argument '{key}' with value {value} is out of bounds [{self.min}, {self.max}].")

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    # Accept either a dict or an iterable of (key, value) pairs
    if isinstance(args, dict):
        items = args.items()
    else:
        items = args
    for key, value in items:
        # Determine if this is a control argument
        if isinstance(key, str) and (key.startswith('_') or key.startswith('control_') or key.startswith('ir_')):
            control_args[key] = value
        else:
            nested_args[key] = value
    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if not extra_vars:
            return vars_dict

        # If extra_vars is a mapping, update directly
        if isinstance(extra_vars, dict):
            vars_dict.update(extra_vars)
        else:
            # Assume an iterable of (key, value) pairs
            for item in extra_vars:
                # Support both tuples/lists and single-element tuples
                if isinstance(item, (list, tuple)) and len(item) == 2:
                    key, value = item
                else:
                    # If only a key is provided, set value to True
                    key = item
                    value = True
                vars_dict[key] = value

        return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import os
    import sys
    import json

    # Build the base command
    cmd = ['ansible-playbook', playbook_path]

    # Handle verbosity
    if verbose is not None:
        if isinstance(verbose, int):
            if verbose > 0:
                cmd.append('-' + 'v' * verbose)
        else:
            # Assume string like '-v' or '--verbose'
            cmd.append(str(verbose))

    # Add any additional ansible-playbook arguments
    if ansible_args:
        for key, value in ansible_args.items():
            # Ensure key starts with '--'
            if not key.startswith('--'):
                key = '--' + key
            if isinstance(value, bool):
                if value:
                    cmd.append(key)
            elif isinstance(value, (list, tuple)):
                for v in value:
                    cmd.extend([key, str(v)])
            else:
                cmd.extend([key, str(value)])

    # Add extra vars if provided
    if extra_vars:
        cmd.extend(['--extra-vars', json.dumps(extra_vars)])

    # Prepare environment
    env = os.environ.copy()
    if ir_workspace and hasattr(ir_workspace, 'env'):
        env.update(ir_workspace.env)

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            env=env,
            check=False
        )
    except FileNotFoundError as e:
        raise RuntimeError("ansible-playbook executable not found") from e

    # Optionally print output if verbose
    if verbose:
        sys.stdout.write(result.stdout)
        sys.stderr.write(result.stderr)

    return result.returncode, result.stdout, result.stderr

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Retrieve expected types for this parser if available
    arg_types = getattr(self, 'parser_arg_types', {}).get(parser_name, {})

    for key, val in list(values_dict.items()):
        # If we know the expected type, try to cast
        if key in arg_types:
            expected_type = arg_types[key]
            try:
                if expected_type is bool:
                    if isinstance(val, str):
                        val_lower = val.lower()
                        if val_lower in ('true', '1', 'yes', 'on'):
                            values_dict[key] = True
                        elif val_lower in ('false', '0', 'no', 'off'):
                            values_dict[key] = False
                        else:
                            values_dict[key] = bool(val)
                    else:
                        values_dict[key] = bool(val)
                else:
                    values_dict[key] = expected_type(val)
            except Exception:
                # If conversion fails, keep original string
                pass
        else:
            # Heuristic conversion for common types
            if isinstance(val, str):
                # Try integer
                try:
                    values_dict[key] = int(val)
                    continue
                except ValueError:
                    pass
                # Try float
                try:
                    values_dict[key] = float(val)
                    continue
                except ValueError:
                    pass
                # Try boolean
                val_lower = val.lower()
                if val_lower in ('true', 'false'):
                    values_dict[key] = val_lower == 'true'
                    continue
                # Try comma-separated list
                if ',' in val:
                    values_dict[key] = [v.strip() for v in val.split(',')]
                    continue

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Find the spec file (JSON or YAML)
    spec_path = None
    for fname in ("plugin.json", "plugin.yaml", "plugin.yml"):
        path = os.path.join(plugin_dir, fname)
        if os.path.isfile(path):
            spec_path = path
            break

    if not spec_path:
        return {}

    # Load the spec file
    with open(spec_path, "r", encoding="utf-8") as f:
        if spec_path.endswith(".json"):
            try:
                data = json.load(f)
            except Exception:
                data = {}
        else:
            try:
                import yaml
                data = yaml.safe_load(f)
            except Exception:
                data = {}

    if not isinstance(data, dict):
        return {}

    # Helper to flatten nested dictionaries
    def _flatten(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    return _flatten(data)

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise ValueError(f"Path '{path}' does not start with root '{root}'")
    stripped = path[len(root):]
    if stripped.startswith('/'):
        stripped = stripped[1:]
    return stripped
